****************************************************************	 Event Manager Patch*	 for Version 2.0 of	ROM*** System Disk 2.0**   Version 2.1  15	Apr 87   Steven E. Glass**   EMStatus was patched to exit more quickly.*** System Disk 4.0** 30 Jun 88	Steven Glass** Added patch to TickCount to turn interrupts off while * tick was being read.** Added patch to PostEvent so it could use AutoKeyLimit.** Added new call SetAutoKeyLimit.** 26-Sep-90	Dave Lyons** Change SysDeathMgr to SysFailMgr so it builds.** 3-Feb-91	Dave Lyons** Changed version to $8301 to match ROM 3 for 6.0.** 11-Feb-91 DAL** Added dispatching of pending SysBeep2 requests to GetNextEvent* (new patch).** 24-Feb-91 DAL** Call UseCoolMousePos from EMStartUp.  If there's a message #6* in MessageCenter, we position the mouse from that now.** 5-Feb-92 DAL** Version $0301 for 6.0 final.***************************************************************** 3-Jun-92 DAL** Version $8302 for 6.0.1d5 (changed UseCoolMousePos in em.asm).** 2-Apr-93 DAL** Version $0302 for 6.0.1.************************************************************************************************************************		               **                Copyright (C) 1986-1993               **                All Rights Reserved	               **                Apple Computer, Inc.	               **		               *********************************************************	include 'all.macros'	include ':::sys.equs.asm'EMVersion	equ $0302	; current version number; Locations in ROMEndCall6	equ $FEFFCEErrOut6	equ $FEFFCE+3EndCall2	equ $FEFFB8ErrOut2	equ $FEFFBB*---------------------------------------------------------------* Constants*---------------------------------------------------------------True	equ $0001False	equ $0000EMTSNum	equ 6	;tool set num for Event MgrInitErr	equ $0601	;duplicate init callResetErr	equ $0602	;can't reset Event MgrActiveErr	equ $0603	;Event Mgr not activeCodeErr	equ $0604	;illegal event codeBtnErr	equ $0605	;illegal button numberSizeErr	equ $0606	;queue size too largeMemErr	equ $0607	;not enough mem for	queueQError	equ $0681	;fatal system error	- damaged queueHError	equ $0682	;fatal system error	- damaged Q handleTaskSig	equ $A55A	;signature word for	heartbeat taskKeyBufParam	equ $2B	;for ReadBParam callClickParam	equ $38	;     "    (change from $2E to $38, Joe Bo)FlashParam	equ $2E	;     "    (change from $2F to $2E, Joe Bo)MouseDown	equ 1	;event codeMouseUp	equ 2	;     "KeyDown	equ 3	;     "AutoKey	equ 5	;     "Update	equ 6	;     "Activate	equ 8	;     "Switch	equ 9	;     "DeskAccessory	equ 10	;     "BUpdate	equ $0040	;bit 6 setBActivate	equ $0100	;bit 8 setBSwitch	equ $0200	;bit 9 setBtn0bit	equ $0080	;used with modifiers fieldBtn1bit	equ $0040	;     "RepeatBit	equ $0800	;used with mod keys	latchMovedBit	equ $2000	;used with BStatMoveIntBit	equ $0002	;     "BtnIntBit	equ $0004	;     "JcTickCount	equ 0	;journal codeJcGetMouse	equ 1	;     "JcButton	equ 2	;     "JcEvent	equ 4	;     "EvtSize	equ 16	;size of event record in bytesEvtQSize	equ 18	;size of event record incl link fieldDefaultQ	equ 20	;default queue sizeMaxQ	equ 3639	;max queue sizeMsgOffset	equ 2	;offset to Message fieldWhenOffset	equ 6	;offset to When fieldWhereOffset	equ 10	;offset to Where fieldModsOffset	equ 14	;offset to Modifiers fieldEvtOffset	equ 2	;offset to event record from start of;		;event queue elementKindOffset	equ 4	;offset to WindowKind field in window*---------------------------------------------------------------* Hardware Equates*---------------------------------------------------------------MouseMode	equ $7F8	;mouse mode byteKeyLatch	equ $C000	;keyboard keypress latchKbdStrobe	equ $C010	;keyboard strobeModLatch	equ $C025	;keyboard modifiers	latchCardType	equ $C02D	;bit 4 specifies internal/external card*---------------------------------------------------------------* Event Manager Zero Page*---------------------------------------------------------------EMZBase	equ 0TempEvent	equ EMZBaseUserEvtPtr	equ TempEvent+16JResultPtr	equ UserEvtPtr+4SaveLink	equ JResultPtr+4TempLink	equ SaveLink+2TempPtr	equ TempLink+2TempBits	equ TempPtr+4SysEventMask	equ TempBits+2	;system event maskQHandle	equ SysEventMask+2	;handle for event queueQPtr	equ QHandle+4	;pointer to event queueQSize	equ QPtr+4	;max number of events in queueQHead	equ QSize+2	;link to first queue elementQTail	equ QHead+2	;link to last queue	elementCheckButton	equ QTail+2WhichButton	equ CheckButton+2GotSwitchCall	equ WhichButton+2	;1 if switch event pending, 0 if notWindowMgr	equ GotSwitchCall+2	;1 if Window Mgr init, 0 if notRemoveEvent	equ WindowMgr+2	;flag used by GetNextEventOSRemoveEvent	equ RemoveEvent+2	;flag used by GetOSEventGotMouse	equ OSRemoveEvent+2	;1 if mouse present, 0 if notExtMouse	equ GotMouse+2	;1 if external mouse, 0 if notMouseAdrs	equ ExtMouse+2	;original mouse vectorKBAdrs	equ MouseAdrs+4	;original keyboard vectorDAAdrs	equ KBAdrs+4	;original desk accesory vectorFBAdrs	equ DAAdrs+4	;original flush buffer vectorVBLAdrs	equ FBAdrs+4	;original VBL vectorKBufOn	equ VBLAdrs+4	;1 if keyboard buffering on before initKBOn	equ KBufOn+2	;1 if keyboard interrupts on before initVBLOn	equ KBOn+2	;1 if VBL interrupts on before initSaveMode	equ VBLOn+2	;original mouse modeSaveP	equ SaveMode+2	;original processor	statusProgID	equ SaveP+2	;program ID used with mem mgrFromGNE	equ ProgID+2	;flag used by GetOSEventAutoKeyLimit	equ FromGNE+2	; added 30 Jun 88 SEGktransRef	equ AutoKeyLimit+2	; added 1/22/89 Mensch (4 byte)kTransFlag	equ kTransRef+4	; added 1/23/89 Mensch (2 Byte)kTransBParamLoc	equ $5A	; battery ram parameter we use...*---------------------------------------------------------------* Window Manager Zero Page (used by Event Manager)*---------------------------------------------------------------WMZBase	equ 128FlgActive	equ WMZBaseFlgDeActive	equ FlgActive+2CurActive	equ FlgDeActive+2CurDeActive	equ CurActive+4CurDeKind	equ CurDeActive+4**************************************************************** EventCallTable2***************************************************************	EXPORT EMCallTable2EMCallTable2	PROC	import EMBootInit2	import EMVersion2	Import EMActive2	import TickCount	import PostEvent	import SetAutoKeyLimit	import getKeyTranslation	import setKeyTranslation	import EMStartup	import GetNextEvent		;11-Feb-91 DAL	import EMShutDownHere	DC.L (TheEnd-Here)/4 ;num calls + 1	DC.L EMBootInit2-1	DC.L EMStartUp-1	DC.L EMShutDown-1	;patched 24-Feb-91 DAL	DC.L EMVersion2-1	DC.L 0	; EMReset-1'	DC.L EMActive2-1	DC.L 0	; oEndCall0-1'	DC.L 0	; oEndCall0-1'	DC.L 0	; DoWindows-1'	DC.L GetNextEvent-1	;patched 11-Feb-91 DAL	DC.L 0	; EventAvail-1'	DC.L 0	; GetMouse-1'	DC.L 0	; Button-1'	DC.L 0	; StillDown-1'	DC.L 0	; WaitMouseUp-1'	DC.L TickCount-1	DC.L 0	; GetDblTime-1'	DC.L 0	; GetCaretTime-1'	DC.L 0	; SetSwitch-1'	DC.L PostEvent-1	DC.L 0	; FlushEvents-1'	DC.L 0	; GetOSEvent-1'	DC.L 0	; OSEventAvail-1'	DC.L 0	; SetEventMask-1'	DC.L 0	; FakeMouse-1'	DC.L SetAutoKeyLimit-1	; added 30 Jun 88 SEG	DC.L GetKeyTranslation-1	; 2/7/89 {$1B06}	DC.L SetKeyTranslation-1	; 2/7/89 {$1C06}TheEnd	ENDP**************************************************************** InitCalls***************************************************************	EXPORT EM2InitCallsEM2InitCalls	PROC;--------------------------------------------------------------;; EMBootInit2;	ENTRY EMBootInit2EMBootInit2	lda #0	clc	rtl;--------------------------------------------------------------;; EMversion2;	ENTRY EMVersion2EMVersion2	lda #EMVersion;--------------------------------------------------------------;; EMActive2;	ENTRY EMActive2EMActive2	sta 7,s	bra EMBootInit2	ENDP;--------------------------------------------------------------;; GetNextEvent;; New patch 11-Feb-91 DAL;	ENTRY GetNextEventGetNextEvent	proc export	import HandlePendingSysBeep2* The stack for HandlePendingSysBeep2 must be just like at tool entry!  It checks* the parameters.	jsr HandlePendingSysBeep2	jml $febed0	;original ROM 1 GetNextEvent	ENDP****************************************************************** TickCount** Change History** 29 Jun 88	Steven Glass** Two things were wrong here.  First the TickCnt was being * accessed with interrupts active and second, if journaling* was active, the journaling code was called with the* wrong direct page register.** To fix this we switch D-reg in and call the old code after* turning interrupts off.*****************************************************************TickCount	PROC	DefineStackorigP	byteorigD	wordRTL1	block 3RTL2	block 3Result	long	phd	; save d-page	tcd	; switch in EM's dpage	php	; turn off interrupts	sei		pha	; call the original code	pha	; 	jsl ToOrigCode		pla	; put result on stack	sta Result+2,s	pla	sta Result+2,s		plp	; restore int state	pld	; restore d-page	bra EMBootInit2	; share exit code	ToOrigCode	jsl $FEC16C	rtl			ENDP*****************************************************************PostEvent	PROC** This patch modifies PostEvent so that suto key events are only * posted if the number of elements in the queue is less than or* equal to a specified limit.  The limit is set to 0 by * EMStartup and an application can change the limit by calling the* new tool call SetAutoKeyLimit.*** Inputs:*	eventCode : word*	eventMsg  : long** Outputs:*	resultCode : word** External Refs:*	MaskTable in ROM*	GetFreeOne in ROM** Entry Points:*	none*	longa on	; mode	longi on** Change History** 30 Jun 88	Steven Glass & Cheryl Ewy** Patch added to allow App to set AutoKeyLimit*****************************************************************	DefineStackOrigD	wordRTL1	block 3RTL2	block 3TheEventMsg	longTheEventCode	wordTheResult	wordMaskTable	equ $FEBAA6+4	; location of mask table in ROM.	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jml ErrOut6Doit	lda TheEventCode,s	;get event code	cmp #16	bcc OK	ldx #CodeErr	;illegal event code	jml ErrOut6	;return the errorOK	php	sei	asl a	tax	lda >MaskTable,x	;get bit mask for code	and <SysEventMask	;is this event enabled?	bne CheckAutoKey	;yes - so check if auto-key eventErrRet	lda #1	;no - so return an error	sta TheResult+1,s	plp	jml EndCall6CheckAutoKey	lda TheEventCode+1,s	;get event code	cmp #AutoKey	;auto-key event?	bne GetFreeOne	;no - so post it	lda <QHead	;is the queue empty?	beq GetFreeOne	;yes - so post the event	lda <QHandle	ora <QHandle+2	bne Handle_OK	PushWord #HError	PushLong #0	_SysFailMgrHandle_OK	lda [<QHandle]	; deref Q handle.	sta <QPtr	ldy #2		lda [<QHandle],y	sta <QPtr+2		ldx #0	; count elements in queue	ldy <QHead	; start with queue headLoop	inx	; bump counter	lda [<QPtr],y	; get link to next element in Q	tay	; repeat till	bne Loop	; none	cpx <AutoKeyLimit	bcs ErrRetGetFreeOne	JML >$FEC23E	; jump back into ROM	ENDP*****************************************************************SetAutoKeyLimit	PROC** Sets the AutoKeyLimit to the value passed.*** Inputs:*	NewLimit** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 30 Jun 88	Steven Glass & Cheryl Ewy** Patch added to allow App to set AutoKeyLimit*****************************************************************	DefineStackOrigD	wordRTL1	block 3RTL2	block 3NewLimit	word	phd	tcd	bne DoIt	ldx #ActiveErr	jml ErrOut2DoIt	lda NewLimit,s	inc a	sta <AutoKeyLimit	jml EndCall2	ENDP*****************************************************************EMStartup	PROC** This routine calls the original EMStartup routine and then* installs the keyboard interrupt handler*** Inputs:*	dPageAddr : word*	queueSize : word*	xMinClamp : word*	xMaxClamp : word*	yMinClamp : word*	yMaxClamp : word*	userID : word** Outputs:*	none** External Refs:	import Keyboard	import UseCoolMousePos	;24-Feb-91 DAL** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackRTL1	block 3RTL2	block 3origD	wordUserID	wordyMaxClamp	wordyMinClamp	wordxMaxClamp	wordxMinClamp	wordqueueSize	worddPageAddr	wordRealEMStartup	equ $FEBB6E	tax	; save orig value of WAP in x	phd	tsc	tcd		pei dPageAddr	; push all the params again	pei queueSize	pei xMinClamp	pei xMaxClamp	pei yMinClamp	pei yMaxClamp	pei UserID	txa	; get wap value back	jsl ToRealEMStartup ; call the real startup code	pha	; save any error code	bcs AnError*** added 24-Feb-91 DAL	jsl UseCoolMousePos*** end of 24-Feb-91 DAL;; Initialize the keyboard here	lda dPageAddr	; init the kTransRef and flag	tcd	stz kTransRef	stz kTransRef+2	stz kTransFlag	pea $FFFF	; special setktrans flag	_SetKeyTranslation	; set up keyboard translation stuff	PushWord #$0F	PushLong #KeyBoard	; keyboard	_SetVector	ldx #00AnError	plx	; pull off the error code returned by orig startup callAnError2	pld	; restore the direct page	ldy #14	; strip the inputs off the stack	jml ToStripToRealEMstartup	jsl RealEMStartup	rtl		ENDP**************************************************************** EMShutDown patch -- 24-Feb-91 DAL** Creates MessageCenter message #6 containing the mouse* position.***************************************************************EMShutDown	proc	import CreateMouseMessage	;24-Feb-91 DAL	tax	beq @notStarted	pha	;save WAP for jumping to ROM	jsl CreateMouseMessage	pla@notStarted	jml $febddf	;original ROM 1 EMShutDown	EndP	END